BEGIN TRANSACTION;
CREATE TABLE applications (
  app_id      INTEGER PRIMARY KEY,
  job_id      INTEGER NOT NULL REFERENCES jobs(job_id),
  applied_on  TEXT NOT NULL,
  status      TEXT DEFAULT 'submitted',
  notes       TEXT
);
CREATE TABLE cities (
  city_id     INTEGER PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  population_approx INTEGER
);
CREATE TABLE employers (
  employer_id INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  sector_id   INTEGER NOT NULL REFERENCES sectors(sector_id),
  city_id     INTEGER NOT NULL REFERENCES cities(city_id),
  hq_in_volusia INTEGER DEFAULT 0,
  is_public   INTEGER DEFAULT 0,
  approx_employees INTEGER,
  avg_annual_wage_override INTEGER,
  description TEXT,
  keywords    TEXT,        -- space-delimited search tokens
  website     TEXT,
  source_verified_date TEXT
, contact_email TEXT, contact_phone TEXT, contact_notes TEXT);
CREATE TABLE hiring_signals (
  signal_id      INTEGER PRIMARY KEY,
  employer_id    INTEGER NOT NULL REFERENCES employers(employer_id),
  signal_type    TEXT NOT NULL,
  source         TEXT,
  date_seen      TEXT NOT NULL,
  date_posted    TEXT,
  title          TEXT,
  family         TEXT,
  pay_min        INTEGER,
  pay_max        INTEGER,
  pay_unit       TEXT,
  remote_eligible INTEGER DEFAULT 0,
  entry_level    INTEGER DEFAULT 0,
  cash_priority  INTEGER DEFAULT 0,
  confidence     TEXT NOT NULL DEFAULT 'inferred',
  signal_tag     TEXT,
  notes          TEXT,
  created_ts     TEXT NOT NULL DEFAULT (datetime('now'))
, hiring_phase TEXT, contact_email TEXT, contact_phone TEXT, contact_notes TEXT);
CREATE TABLE jobs (
  job_id      INTEGER PRIMARY KEY,
  employer_id INTEGER NOT NULL REFERENCES employers(employer_id),
  title       TEXT NOT NULL,
  family      TEXT,        -- e.g. Nursing, Engineering, Teaching
  remote_eligible INTEGER DEFAULT 0,
  entry_level INTEGER DEFAULT 0,
  posted_date TEXT,
  url         TEXT,
  source      TEXT
, pay_type TEXT, pay_min INTEGER, pay_max INTEGER, pay_unit TEXT, posted_ts TEXT, apply_url TEXT, cash_priority INTEGER DEFAULT 0, notes TEXT, apply_email TEXT, apply_phone TEXT, apply_notes TEXT);
CREATE TABLE sectors (
  sector_id   INTEGER PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  color       TEXT
);
CREATE INDEX idx_hiring_signals_employer ON hiring_signals(employer_id);
CREATE INDEX idx_hiring_signals_type ON hiring_signals(signal_type);
CREATE INDEX idx_hiring_signals_confidence ON hiring_signals(confidence);
COMMIT;
